1	"use client";
2	
3	import { useEffect, useRef, useState } from "react";
4	import { placeHostingOrder, startHostingCardSetup, checkHostingSubdomain } from "@/lib/actions-hosting";
5	import { finalizeCardSetup } from "@/lib/actions-payment-method";
6	import { termPriceCents, ANNUAL_TERM_MONTHS, DEFAULT_ANNUAL_DISCOUNT_PCT, PRODUCT_TERMS, vpsTerm } from "@/lib/billing-terms";
7	import { extraDiskCentsAt, EXTRA_DISK_STEP_GB, EXTRA_DISK_MAX_ADD_GB, EXTRA_DISK_ONE_WAY_NOTE, EXTRA_DISK_DEFAULT_PER_GB_CENTS } from "@/lib/extra-disk";
8	import { TermLadder } from "@/components/customer/TermLadder";
9	import { StripeCheckoutModal } from "@/components/customer/StripeCheckoutModal";
10	import { recommendHostingPlan } from "@/lib/hosting/recommend";
11	
12	/* --------------------------------------------------------------- types --- */
13	
14	export type WizardPlan = {
15	  id: string;
16	  name: string;
17	  priceCents: number;
18	  diskGB: number;
19	  maxSites: number;
20	  maxDatabases: number;
21	  bandwidthTB: number;
22	  mailboxes: number;
23	  freeMigration: boolean;
24	  featured: boolean;
25	  tagline: string;
26	};
27	
28	type AppOpt = { slug: string; name: string; needsDb: boolean; blurb?: string; logoPath?: string; logoHex?: string };
29	
30	const money = (c: number) => `$${(c / 100).toFixed(2)}`;
31	
32	/** sessionStorage key for the in-progress order — survives the Stripe card round-trip. */
33	const DRAFT_KEY = "nxeon.hosting.deploy.draft.v1";
34	type Draft = {
35	  step: number;
36	  planId: string;
37	  termMonths: number;
38	  domainMode: "temp" | "own";
39	  domain: string;
40	  /** The chosen free-subdomain label — MUST persist across the card-setup round-trip,
41	   *  else a customer who typed "testing" gets the auto-derived name after adding a card. */
42	  subLabel: string;
43	  extraDiskGB: number;
44	  appSlug: string;
45	};
46	
47	/**
48	 * The one-month first-month-free credit, computed EXACTLY like the server's
49	 * `firstMonthCreditCents` (kept inline so this client file never imports the
50	 * db-backed promo module). A 1-month term is wholly free; a longer term credits a
51	 * single month. The server recomputes the real debit with the same formula, so
52	 * displayed === charged.
53	 */
54	function firstMonthCredit(fullCents: number, months: number): number {
55	  if (months <= 1) return fullCents;
56	  return Math.min(fullCents, Math.round(fullCents / months));
57	}
58	
59	function Stepper({ step, steps }: { step: number; steps: string[] }) {
60	  return (
61	    <div className="mb-6 flex flex-wrap items-center gap-2 text-xs">
62	      {steps.map((s, i) => (
63	        <div key={s} className="flex items-center gap-2">
64	          <span
65	            className={`flex h-6 w-6 items-center justify-center rounded-full border text-[11px] font-semibold ${
66	              i === step
67	                ? "border-brand-400 bg-brand-500/20 text-brand-200"
68	                : i < step
69	                  ? "border-emerald-500/40 bg-emerald-500/15 text-emerald-300"
70	                  : "border-white/10 text-slate-500"
71	            }`}
72	          >
73	            {i < step ? "✓" : i + 1}
74	          </span>
75	          <span className={i === step ? "text-white" : "text-slate-500"}>{s}</span>
76	          {i < steps.length - 1 && <span className="mx-1 text-slate-700">→</span>}
77	        </div>
78	      ))}
79	    </div>
80	  );
81	}
82	
83	/* -------------------------------------------------------------- wizard --- */
84	
85	export function HostingDeployWizard({
86	  plans,
87	  apps,
88	  annualDiscountPct = DEFAULT_ANNUAL_DISCOUNT_PCT,
89	  firstMonthFree = false,
90	  balanceCents,
91	  hasCard,
92	  cardLabel,
93	  stripeReady,
94	  tempSubdomainBase,
95	  extraDiskPerGbCents = EXTRA_DISK_DEFAULT_PER_GB_CENTS,
96	}: {
97	  plans: WizardPlan[];
98	  apps: AppOpt[];
99	  annualDiscountPct?: number;
100	  firstMonthFree?: boolean;
101	  balanceCents: number;
102	  /** A renewal-capable card is already on file (charged off-session at renewal). */
103	  hasCard: boolean;
104	  cardLabel: string | null;
105	  /** Stripe is configured, so we can capture a card at all. */
106	  stripeReady: boolean;
107	  /** Base zone for the free temporary subdomain, e.g. "nxeon.cloud". */
108	  tempSubdomainBase: string;
109	  /** Price per extra GB / month (cents) — the same add-on rate VPS uses. */
110	  extraDiskPerGbCents?: number;
111	}) {
112	  // Steps: Install is only shown when there's an app catalog to pick from.
113	  const hasApps = apps.length > 0;
114	  const steps = ["Plan", "Domain", ...(hasApps ? ["Install"] : []), "Add-ons", "Review"];
115	  const [step, setStep] = useState(0);
116	
117	  const [planId, setPlanId] = useState(plans[0]?.id ?? "");
118	  const [termMonths, setTermMonths] = useState(ANNUAL_TERM_MONTHS);
119	  const [domainMode, setDomainMode] = useState<"temp" | "own">("temp");
120	  const [domain, setDomain] = useState("");
121	  // Optional customer-chosen free-subdomain label. Empty => the server auto-derives
122	  // `<username>.<base>`. When the customer types one we live-check availability so a
123	  // taken/invalid label is caught before the order (the order re-checks atomically).
124	  const [subLabel, setSubLabel] = useState("");
125	  const [subCheck, setSubCheck] = useState<{ status: "idle" | "checking" | "ok" | "bad"; reason?: string }>({ status: "idle" });
126	  const [extraDiskGB, setExtraDiskGB] = useState(0);
127	  const [appSlug, setAppSlug] = useState("");
128	
129	  // A card the customer just saved via the Stripe round-trip flips this true
130	  // without a page reload, so the Review step stops asking for one.
131	  const [savedCard, setSavedCard] = useState(hasCard);
132	
133	  const [busy, setBusy] = useState(false);
134	  const [error, setError] = useState("");
135	  const [cardBusy, setCardBusy] = useState(false);
136	  const [cardNote, setCardNote] = useState("");
137	  const [cardCheckout, setCardCheckout] = useState<{ clientSecret: string; publishableKey: string } | null>(null);
138	  const [restoredAfterSetup, setRestoredAfterSetup] = useState(false);
139	
140	  // ONE idempotency token per wizard mount. A double-click is stopped by `busy`;
141	  // this token is the server-side guard against a network retry creating a second
142	  // account (placeHostingOrder → FulfilledSession UNIQUE). A user-driven retry
143	  // after a failure reuses it safely (the server clears a FAILED marker).
144	  const idemRef = useRef<string>("");
145	  if (!idemRef.current) idemRef.current = makeToken();
146	
147	  const plan = plans.find((p) => p.id === planId) ?? null;
148	  const curLabel = steps[step];
149	  const isLast = step === steps.length - 1;
150	
151	  /* ----- pricing (all DB-fed; the server recomputes the debit identically) -- */
152	  const planTermCents = plan ? termPriceCents(plan.priceCents, termMonths, annualDiscountPct) : 0;
153	  // Extra storage add-on: priced per GB/mo over the term, and NEVER discounted by the
154	  // first-month-free promo (mirrors the server — the credit applies to the plan only).
155	  const extraTermCents = extraDiskCentsAt(extraDiskGB, extraDiskPerGbCents) * termMonths;
156	  const fullTermCents = planTermCents + extraTermCents;
157	  const creditCents = firstMonthFree ? firstMonthCredit(planTermCents, termMonths) : 0;
158	  const dueTodayCents = Math.max(0, planTermCents - creditCents) + extraTermCents;
159	  // What the account renews at — the full term price (plan + storage), promo aside.
160	  const renewalCents = fullTermCents;
161	  const perMonthCents = Math.round(planTermCents / Math.max(1, termMonths));
162	  const termWord = termMonths === ANNUAL_TERM_MONTHS ? "year" : termMonths === 1 ? "month" : `${termMonths} mo`;
163	
164	  // Can we bill the renewal? A saved card OR a wallet already holding a renewal's
165	  // worth. This mirrors the server gate in placeHostingOrder exactly.
166	  const renewalMethodOk = savedCard || balanceCents >= renewalCents;
167	
168	  /* ----- Stripe card round-trip (draft save + restore) ---------------------- */
169	  useEffect(() => {
170	    let sid = "";
171	    try {
172	      sid = new URLSearchParams(window.location.search).get("card_setup") ?? "";
173	    } catch {
174	      /* no URL access */
175	    }
176	    if (!sid) return;
177	    // Pull our draft back so the customer lands where they left off.
178	    let d: Draft | null = null;
179	    try {
180	      const raw = sessionStorage.getItem(DRAFT_KEY);
181	      sessionStorage.removeItem(DRAFT_KEY);
182	      if (raw) d = JSON.parse(raw) as Draft;
183	    } catch {
184	      d = null;
185	    }
186	    if (d) {
187	      if (plans.some((p) => p.id === d.planId)) setPlanId(d.planId);
188	      if (PRODUCT_TERMS.some((t) => t.months === d.termMonths)) setTermMonths(d.termMonths);
189	      if (d.domainMode === "temp" || d.domainMode === "own") setDomainMode(d.domainMode);
190	      if (typeof d.domain === "string") setDomain(d.domain);
191	      if (typeof d.subLabel === "string") setSubLabel(d.subLabel);
192	      if (Number.isFinite(d.extraDiskGB)) setExtraDiskGB(Math.max(0, Math.min(EXTRA_DISK_MAX_ADD_GB, Math.round(d.extraDiskGB))));
193	      if (apps.some((a) => a.slug === d.appSlug)) setAppSlug(d.appSlug);
194	    }
195	    setRestoredAfterSetup(true);
196	    setStep(steps.length - 1); // land on Review
197	    if (sid === "canceled") {
198	      setCardNote("Card setup was cancelled — you weren’t charged. Add a card to enable renewals, or use your wallet.");
199	      return;
200	    }
201	    // Finalise the saved card, then reflect it on the Review step.
202	    (async () => {
203	      const res = await finalizeCardSetup(sid);
204	      if (res.ok) {
205	        setSavedCard(true);
206	        setCardNote(`Card saved${res.label ? ` — ${res.label}` : ""}. Your renewals will bill to it.`);
207	        // Fire-and-forget "card" conversion (→ Meta AddPaymentInfo + the Google Ads
208	        // card label). Best-effort: a no-op until consent + the pixel load.
209	        try {
210	          (window as unknown as { nxTrack?: (k: string, p?: Record<string, unknown>) => void }).nxTrack?.("card", {});
211	        } catch {
212	          /* ignore */
213	        }
214	      } else {
215	        setCardNote(res.error ?? "We couldn’t save that card. Try again or use your wallet.");
216	      }
217	    })();
218	    // Mount-only restore.
219	    // eslint-disable-next-line react-hooks/exhaustive-deps
220	  }, []);
221	
222	  function saveDraft() {
223	    try {
224	      const d: Draft = { step, planId, termMonths, domainMode, domain, subLabel, extraDiskGB, appSlug };
225	      sessionStorage.setItem(DRAFT_KEY, JSON.stringify(d));
226	    } catch {
227	      /* storage disabled — the card flow still works, it just won't restore */
228	    }
229	  }
230	
231	  async function addCard() {
232	    setCardBusy(true);
233	    setCardNote("");
234	    saveDraft();
235	    try {
236	      const res = await startHostingCardSetup();
237	      if (res.clientSecret && res.publishableKey) {
238	        // Open the embedded card modal on THIS page — no redirect to Stripe.
239	        setCardCheckout({ clientSecret: res.clientSecret, publishableKey: res.publishableKey });
240	        return;
241	      }
242	      setCardNote(res.error ?? "We couldn’t start card setup just now. Please try again.");
243	    } catch {
244	      setCardNote("We couldn’t start card setup just now. Please try again.");
245	    } finally {
246	      setCardBusy(false);
247	    }
248	  }
249	
250	  /* ----- domain validity (client-side friendliness; server re-validates) ---- */
251	  const domainTrim = domain.trim().toLowerCase();
252	  const domainLooksValid = /^([a-z0-9]([a-z0-9-]*[a-z0-9])?\.)+[a-z]{2,}$/.test(domainTrim);
253	  const domainBlocker =
254	    domainMode === "own" && !domainLooksValid
255	      ? domainTrim.length === 0
256	        ? "Enter the domain you want to host, or switch to a free temporary subdomain."
257	        : "Enter a valid domain (e.g. example.com)."
258	      : null;
259	
260	  // Live availability check for a chosen free subdomain (debounced). An empty label
261	  // is allowed — the server auto-derives `<username>.<base>` — so only a typed label
262	  // that isn't confirmed available blocks the flow.
263	  const subLabelTrim = subLabel.trim().toLowerCase();
264	  useEffect(() => {
265	    if (domainMode !== "temp") {
266	      setSubCheck({ status: "idle" });
267	      return;
268	    }
269	    const label = subLabel.trim().toLowerCase();
270	    if (!label) {
271	      setSubCheck({ status: "idle" });
272	      return;
273	    }
274	    setSubCheck({ status: "checking" });
275	    let cancelled = false;
276	    const t = setTimeout(async () => {
277	      try {
278	        const r = await checkHostingSubdomain(label);
279	        if (!cancelled) setSubCheck(r.available ? { status: "ok" } : { status: "bad", reason: r.reason });
280	      } catch {
281	        if (!cancelled) setSubCheck({ status: "bad", reason: "Couldn’t check right now — try again." });
282	      }
283	    }, 400);
284	    return () => {
285	      cancelled = true;
286	      clearTimeout(t);
287	    };
288	  }, [subLabel, domainMode]);
289	
290	  const subdomainBlocker =
291	    domainMode === "temp" && subLabelTrim.length > 0 && subCheck.status !== "ok"
292	      ? subCheck.status === "checking"
293	        ? "Checking availability…"
294	        : subCheck.reason ?? "Pick an available subdomain."
295	      : null;
296	
297	  const canContinue = curLabel === "Domain" ? !domainBlocker && !subdomainBlocker : true;
298	  const canPlace = !!planId && !busy && !domainBlocker && !subdomainBlocker;
299	
300	  async function place() {
301	    if (!plan) return;
302	    setBusy(true);
303	    setError("");
304	    try {
305	      const res = await placeHostingOrder({
306	        planId,
307	        domain: domainMode === "own" ? domainTrim : undefined,
308	        subdomainLabel: domainMode === "temp" && subLabelTrim ? subLabelTrim : undefined,
309	        extraDiskGB: extraDiskGB || undefined,
310	        termMonths,
311	        appSlug: appSlug || undefined,
312	        idempotencyKey: idemRef.current,
313	      });
314	      if ("needCard" in res) {
315	        setCardNote("Add a renewal payment method to continue — a $0 first month still needs a way to bill month two.");
316	        setStep(steps.length - 1);
317	        return;
318	      }
319	      if ("error" in res) {
320	        setError(res.error || "Something went wrong. Your wallet was not charged — try again.");
321	        return;
322	      }
323	      try {
324	        sessionStorage.removeItem(DRAFT_KEY);
325	      } catch {
326	        /* ignore */
327	      }
328	      // Fire the "hosting" conversion for a completed hosting signup (→ Meta
329	      // Subscribe + the Google Ads hosting label). The first-month-free ad funnel
330	      // optimizes toward THIS event, not Purchase: the order is $0 today (free
331	      // month) and the real revenue is the renewal, so Purchase would be a $0/late
332	      // signal. `nxTrack` is the consent-gated global from ConversionTags — a no-op
333	      // until the visitor consents + the pixel loads.
334	      try {
335	        (window as unknown as { nxTrack?: (k: string, p?: Record<string, unknown>) => void }).nxTrack?.(
336	          "hosting",
337	          // Value = the recurring term charge (what they renew at — first month is
338	          // free, so this is the real subscription value for ROAS, not $0-today).
339	          { value: renewalCents / 100, currency: "USD", eventId: idemRef.current },
340	        );
341	      } catch {
342	        /* ignore */
343	      }
344	      window.location.href = `/dashboard/hosting/${res.accountId}`;
345	      return;
346	    } catch {
347	      setError("Something went wrong. Your wallet was not charged — try again.");
348	    } finally {
349	      setBusy(false);
350	    }
351	  }
352	
353	  const domainForReview =
354	    domainMode === "own"
355	      ? domainTrim || "—"
356	      : subLabelTrim
357	        ? `${subLabelTrim}.${tempSubdomainBase} (free — live instantly, no DNS to set up)`
358	        : `a free ${tempSubdomainBase} subdomain (connect a real domain anytime)`;
359	  const appName = apps.find((a) => a.slug === appSlug)?.name ?? "None";
360	
361	  return (
362	    <div className="card">
363	      {cardCheckout && (
364	        <StripeCheckoutModal
365	          clientSecret={cardCheckout.clientSecret}
366	          publishableKey={cardCheckout.publishableKey}
367	          title="Add a payment method"
368	          onClose={() => setCardCheckout(null)}
369	        />
370	      )}
371	      <Stepper step={step} steps={steps} />
372	
373	      {restoredAfterSetup && cardNote && (
374	        <div className="mb-4 rounded-xl border border-white/[0.08] bg-white/[0.03] px-3 py-2 text-sm text-slate-300">{cardNote}</div>
375	      )}
376	      {error && <div className="mb-4 rounded-xl border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-300">{error}</div>}
377	
378	      {/* -------------------------------------------------------- Plan --- */}
379	      {curLabel === "Plan" && (
380	        <div>
381	          <h2 className="mb-1 font-semibold">Choose your plan</h2>
382	          <p className="mb-4 text-sm text-slate-400">
383	            Each account is isolated with its own storage, databases and email. Commit longer to pay less per month —
384	            you can change the term below.
385	          </p>
386	          {plans.length === 0 ? (
387	            <p className="text-sm text-slate-400">No hosting plans are available yet. Check back soon.</p>
388	          ) : (
389	            <>
390	              <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
391	                {plans.map((p) => {
392	                  const rec = recommendHostingPlan(p);
393	                  const selected = planId === p.id;
394	                  return (
395	                    <button
396	                      key={p.id}
397	                      type="button"
398	                      onClick={() => setPlanId(p.id)}
399	                      className={`relative flex flex-col rounded-xl border px-4 py-3 text-left transition ${
400	                        selected ? "!border-brand-400 ring-1 ring-brand-400 bg-brand-500/10" : p.featured ? "border-brand-500/40 hover:border-brand-400" : "border-white/10 hover:border-white/20"
401	                      }`}
402	                    >
403	                      {p.featured && (
404	                        <span className="absolute -top-2 right-3 rounded-full bg-brand-500 px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wide text-white">
405	                          Most popular
406	                        </span>
407	                      )}
408	                      <div className="flex items-baseline justify-between gap-2">
409	                        <span className="font-medium">{p.name}</span>
410	                        {firstMonthFree ? (
411	                          <span className="text-right leading-tight">
412	                            <span className="block text-xs font-bold uppercase tracking-wide text-emerald-300">Free first month</span>
413	                            <span className="block text-[11px] text-slate-500">then {money(p.priceCents)}/mo</span>
414	                          </span>
415	                        ) : (
416	                          <span className="text-sm font-semibold">
417	                            {money(p.priceCents)}
418	                            <span className="text-xs text-slate-500">/mo</span>
419	                          </span>
420	                        )}
421	                      </div>
422	                      <p className="mt-1.5 text-xs font-medium text-brand-200">{p.tagline || rec.headline}</p>
423	                      <ul className="mt-2 space-y-0.5 text-xs text-slate-400">
424	                        <li>{p.diskGB} GB NVMe SSD storage</li>
425	                        <li>{p.maxSites} website{p.maxSites === 1 ? "" : "s"}</li>
426	                        <li>{p.maxDatabases} database{p.maxDatabases === 1 ? "" : "s"}</li>
427	                        <li>{p.bandwidthTB} TB bandwidth</li>
428	                        <li>{p.mailboxes} mailbox{p.mailboxes === 1 ? "" : "es"} · free SSL</li>
429	                        {p.freeMigration && <li className="text-emerald-300/90">✓ Free website migration</li>}
430	                      </ul>
431	                    </button>
432	                  );
433	                })}
434	              </div>
435	              {plan && (
436	                <div className="mt-5">
437	                  <div className="mb-1.5 flex items-baseline justify-between gap-2">
438	                    <label className="label mb-0">Billing term</label>
439	                    <span className="text-[11px] text-slate-500">Commit longer, pay less per month</span>
440	                  </div>
441	                  <TermLadder monthlyCents={plan.priceCents} annualDiscountPct={annualDiscountPct} value={termMonths} onChange={setTermMonths} />
442	                </div>
443	              )}
444	            </>
445	          )}
446	        </div>
447	      )}
448	
449	      {/* ------------------------------------------------------ Domain --- */}
450	      {curLabel === "Domain" && (
451	        <div>
452	          <h2 className="mb-1 font-semibold">Where should your site live?</h2>
453	          <p className="mb-4 text-sm text-slate-400">
454	            You don’t need a domain to get started — begin on a free temporary subdomain and connect a real domain
455	            whenever you’re ready.
456	          </p>
457	          <div className="grid gap-3 sm:grid-cols-2">
458	            <button
459	              type="button"
460	              onClick={() => setDomainMode("temp")}
461	              className={`card p-4 text-left transition ${domainMode === "temp" ? "!border-brand-400 ring-1 ring-brand-400" : "hover:border-white/20"}`}
462	            >
463	              <div className="mb-1 flex items-center justify-between">
464	                <span className="text-sm font-semibold">Free temporary subdomain</span>
465	                <span className="rounded bg-emerald-500/15 px-1.5 py-0.5 text-[10px] text-emerald-300">Recommended</span>
466	              </div>
467	              <p className="text-xs text-slate-400">
468	                Go live instantly on <span className="font-mono text-slate-300">yourname.{tempSubdomainBase}</span>. Add
469	                your own domain from the panel later — no re-order needed.
470	              </p>
471	            </button>
472	            <button
473	              type="button"
474	              onClick={() => setDomainMode("own")}
475	              className={`card p-4 text-left transition ${domainMode === "own" ? "!border-brand-400 ring-1 ring-brand-400" : "hover:border-white/20"}`}
476	            >
477	              <div className="mb-1 flex items-center justify-between">
478	                <span className="text-sm font-semibold">Use my own domain</span>
479	              </div>
480	              <p className="text-xs text-slate-400">
481	                Already own a domain? Enter it and we’ll give you the exact DNS record to point it at us.
482	              </p>
483	            </button>
484	          </div>
485	          {domainMode === "own" && (
486	            <div className="mt-4 max-w-sm">
487	              <label className="label" htmlFor="hosting-domain">
488	                Your domain
489	              </label>
490	              <input
491	                id="hosting-domain"
492	                className="input"
493	                placeholder="example.com"
494	                value={domain}
495	                onChange={(e) => setDomain(e.target.value)}
496	                aria-invalid={!!domainBlocker}
497	              />
498	              {domainBlocker && <p className="mt-1 text-xs text-amber-300">{domainBlocker}</p>}
499	            </div>
500	          )}
501	          {domainMode === "temp" && (
502	            <div className="mt-4 max-w-md">
