5	/**
6	 * The persuasive billing-term ladder — ONE shared, DB-fed presentation of the
7	 * "commit longer, pay less" choice, used by every non-VPS product order flow
8	 * (Shared Hosting, Business Email, Game servers, NxCloud). The VPS deploy wizard
9	 * keeps its own richer ladder because it also layers a first-term promo and
10	 * per-term add-ons on top; everything here is the clean two-choice case.
11	 *
12	 * TRUTH BY CONSTRUCTION. Every number shown is derived from the caller's real
13	 * monthly base price (`monthlyCents`, a db.*Plan.priceCents) run through
14	 * `termPriceCents` with the SAME live `annualDiscountPct` the server charges and
15	 * renews at — see lib/order.ts / renewalCharge. Nothing here is a marketing
16	 * literal: the effective $/mo, the % off, the total billed and the amount saved
17	 * are all functions of the catalogue, so a plan edit or an admin discount change
18	 * propagates automatically and the ladder can never advertise a figure checkout
19	 * won't honour.
20	 *
21	 * PERSUASION: the longest term with a real discount is badged "Best value"; the
22	 * annual term (when it isn't itself the longest) is badged "Recommended". Callers
23	 * default their selection to the recommended (annual) term — monthly stays one
24	 * click away, clearly labelled "cancel anytime", so the nudge is honest.
25	 */
26	
27	const money = (c: number) => `$${(c / 100).toFixed(2)}`;
28	
29	export function TermLadder({
30	  monthlyCents,
31	  annualDiscountPct,
32	  value,
33	  onChange,
34	  terms = PRODUCT_TERMS,
35	  columns,
36	  size = "md",
37	}: {
38	  /** The plan's real monthly base price in cents (db.*Plan.priceCents). */
39	  monthlyCents: number;
40	  /** Live admin annual discount (%), passed through untouched to termPriceCents. */
41	  annualDiscountPct: number;
42	  /** Currently-selected term in months. */
43	  value: number;
44	  onChange: (months: number) => void;
45	  /** Which term set to render. Defaults to Monthly + Annual (the non-VPS products). */
46	  terms?: VpsTerm[];
47	  /** Tailwind grid-cols utility for the ladder row. */
48	  columns?: string;
49	  size?: "sm" | "md";
50	}) {
51	  const longestMonths = terms.reduce((m, t) => Math.max(m, t.months), 0);
52	  // Default layout scales with the number of terms: a 4-term ladder gets a 2×2 →
53	  // 4-up grid, the classic 2-term case stays side-by-side. Callers can override.
54	  const gridCols = columns ?? (terms.length > 2 ? "grid-cols-2 lg:grid-cols-4" : "sm:grid-cols-2");
55	
56	  return (
57	    <div className={`grid gap-3 ${gridCols}`}>
58	      {terms.map((t) => {
59	        const total = termPriceCents(monthlyCents, t.months, annualDiscountPct);
60	        const perMo = Math.round(total / t.months);
61	        const monthlyRun = monthlyCents * t.months;
62	        const savings = monthlyRun - total;
63	        const disc = t.months === ANNUAL_TERM_MONTHS ? annualDiscountPct : t.discountPct;
64	        const on = value === t.months;
65	        const isMonthly = t.months === 1;
66	        const isLongest = t.months === longestMonths;
67	        const isAnnual = t.months === ANNUAL_TERM_MONTHS;
68	        // Best value = the longest term that actually discounts. Recommended =
69	        // annual, when a longer term outranks it (VPS-style 2/3-yr ladders).
70	        const ribbon = isLongest && disc > 0 ? "Best value" : isAnnual && disc > 0 ? "Recommended" : null;
71	        // Effective saving headline: annual reads "/yr", multi-year reads over the term.
72	        const savingLabel = isAnnual
73	          ? `Save ${money(savings)}/yr`
74	          : `Save ${money(savings)} over ${t.short}`;
75	
76	        return (
77	          <button
78	            key={t.months}
79	            type="button"
80	            onClick={() => onChange(t.months)}
81	            aria-pressed={on}
82	            className={`group relative rounded-2xl border ${size === "sm" ? "p-3.5" : "p-4"} text-left transition ${
83	              on
84	                ? "border-brand-400 bg-brand-500/10 ring-1 ring-brand-400/40"
85	                : ribbon
86	                  ? "border-emerald-500/25 bg-emerald-500/[0.04] hover:border-emerald-400/50"
87	                  : "border-white/10 bg-white/[0.02] hover:border-white/25"
88	            }`}
89	          >
90	            {ribbon && (
91	              <span
92	                className={`absolute -top-2.5 left-4 rounded-full px-2 py-0.5 text-[10px] font-bold uppercase tracking-wider text-white shadow ${
93	                  ribbon === "Best value" ? "bg-gradient-to-r from-emerald-500 to-teal-500" : "bg-gradient-to-r from-accent-blue to-brand-500"
94	                }`}
95	              >
96	                {ribbon}
97	              </span>
98	            )}
99	            <div className="flex items-center justify-between gap-2">
100	              <span className="text-sm font-semibold text-white">{t.label}</span>
101	              {disc > 0 && (
102	                <span className="rounded-full bg-emerald-500/15 px-1.5 py-0.5 text-[10px] font-semibold text-emerald-300">
103	                  −{disc}%
104	                </span>
105	              )}
106	            </div>
107	            <p className="mt-1.5 flex items-baseline gap-1.5">
108	              <span className={`${size === "sm" ? "text-lg" : "text-2xl"} font-bold text-white tabular-nums`}>{money(perMo)}</span>
109	              <span className="text-xs text-slate-400">/mo</span>
110	              {disc > 0 && <span className="text-xs text-slate-500 line-through tabular-nums">{money(monthlyCents)}</span>}
111	            </p>
112	            <p className="mt-1 text-[11px] text-slate-500">
113	              {money(total)} billed {isMonthly ? "monthly" : `every ${t.short}`}
114	            </p>
115	            {savings > 0 ? (
116	              <p className="mt-1 text-[11px] font-semibold text-emerald-300">{savingLabel}</p>
117	            ) : (
118	              <p className="mt-1 text-[11px] text-slate-500">Flexible — cancel anytime</p>
119	            )}
120	          </button>
121	        );
122	      })}
123	    </div>
124	  );
125	}
